function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`show ${error?'error':''}`;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.className='',4200)}
async function api(url,options={}){const headers={...(options.headers||{})};if(options.body&&!(options.body instanceof FormData))headers['Content-Type']='application/json';if(['POST','PUT','PATCH','DELETE'].includes((options.method||'GET').toUpperCase()))headers['X-CSRF-Token']=document.querySelector('meta[name="csrf-token"]')?.content||'';const response=await fetch(url,{...options,headers});if(response.status===401){window.location.assign(`/login?next=${encodeURIComponent(window.location.pathname+window.location.search)}`);throw new Error('Sign in required')}if(!response.ok){let body={};try{body=await response.json()}catch{}const detail=body.detail;throw new Error(typeof detail==='object'?(detail.message||JSON.stringify(detail)):(detail||`Request failed (${response.status})`))}if(response.status===204)return null;return response.json()}
async function logout(){try{await api('/logout',{method:'POST'});window.location.assign('/login')}catch(error){toast(error.message,true)}}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function money(value){return value==null?'—':new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(value))}
function availabilityLabel(row){if(row.available)return'Available';const name=String(row.rostered_by||'').trim();return name&&!/^\d+$/.test(name)?name:'Team name unavailable'}
function profileHref(row){return `/player/${encodeURIComponent(row.player_id)}?league_id=${encodeURIComponent(activeLeagueId())}`}
function playerFlags(row){const flags=[];if(row.rookie)flags.push('<span class="player-flag rookie">Rookie</span>');if(row.injury_status)flags.push(`<span class="player-flag injury">${escapeHtml(row.injury_status)}</span>`);if(row.source_confidence==='low')flags.push('<span class="player-flag limited">Limited sources</span>');return flags.join(' ')}
function switchLeague(value){const url=new URL(location.href);url.searchParams.set('league_id',value);location.href=url}
function shortDate(value){if(!value)return'Never';return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
async function syncMfl(){const button=document.querySelector('#sync-button');if(button){button.disabled=true;button.textContent='Synchronizing…'}try{const result=await api('/api/sync',{method:'POST'});toast(`Synchronized ${result.leagues.length} league(s)`);location.reload()}catch(error){toast(error.message,true);if(button){button.disabled=false;button.textContent='Synchronize MFL'}}}

document.addEventListener('keydown',event=>{if(event.key==='?'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){event.preventDefault();document.querySelector('#shortcut-help')?.showModal()}if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){const search=document.querySelector('input[type=search]');if(search){event.preventDefault();search.focus()}}if(event.key==='Escape'){document.querySelectorAll('dialog[open]').forEach(item=>item.close());const chat=document.querySelector('#assistant-window');if(chat&&!chat.hidden)closeAssistant()}})

function setSelectOptions(selector,items,allLabel='All positions'){const select=document.querySelector(selector);if(!select)return;const selected=select.value;select.innerHTML=`<option value="">${escapeHtml(allLabel)}</option>`+items.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join('');select.value=items.includes(selected)?selected:''}
function initResizableTables(){document.querySelectorAll('.table-wrap table').forEach((table,tableIndex)=>{if(table.dataset.resizableReady||!table.tHead?.rows.length)return;const headers=[...table.tHead.rows[0].cells];if(headers.length<2)return;table.dataset.resizableReady='true';table.classList.add('resizable-table');const storageKey=table.dataset.columnKey||`draftdesk:columns:${location.pathname}:${tableIndex}`;let saved=[];try{saved=JSON.parse(localStorage.getItem(storageKey)||'[]')}catch{}const widths=headers.map((header,index)=>Math.max(60,Number(saved[index])||Math.ceil(header.getBoundingClientRect().width)));const group=document.createElement('colgroup');const columns=widths.map(width=>{const column=document.createElement('col');column.style.width=`${width}px`;group.appendChild(column);return column});table.insertBefore(group,table.firstChild);const apply=()=>{columns.forEach((column,index)=>column.style.width=`${widths[index]}px`);localStorage.setItem(storageKey,JSON.stringify(widths))};headers.slice(0,-1).forEach((header,index)=>{const handle=document.createElement('span');handle.className='column-resizer';handle.title='Drag to resize column';handle.addEventListener('pointerdown',event=>{event.preventDefault();handle.setPointerCapture(event.pointerId);const startX=event.clientX,current=widths[index],next=widths[index+1];const move=moveEvent=>{const delta=Math.max(60-current,Math.min(next-60,moveEvent.clientX-startX));widths[index]=current+delta;widths[index+1]=next-delta;apply()};const stop=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',stop);handle.removeEventListener('pointercancel',stop)};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop)});header.appendChild(handle)});apply()})}
document.addEventListener('DOMContentLoaded',initResizableTables)

let rankings=[];let auctionState=null;let auctionSort='overall_rank';let auctionDirection='asc';let saleMatchTimer=null;let adminNominationState=null;let adminNominationLeagueId='';let adminNominationDragIndex=null;
async function refreshAuction(){const selectedId=document.querySelector('#sale-player-id')?.value||'';[auctionState,rankings]=await Promise.all([api(`/api/auction/state?league_id=${encodeURIComponent(AUCTION_LEAGUE_ID)}`),api(`/api/leagues/${encodeURIComponent(AUCTION_LEAGUE_ID)}/rankings`)]);const order=['QB','RB','WR','TE','PK','DEF'];const positions=[...new Set(rankings.map(row=>row.position))].sort((a,b)=>order.indexOf(a)-order.indexOf(b));setSelectOptions('#position-filter',positions);setSelectOptions('#auction-position-filter',positions,'All');renderPlayerMatcher();renderBudgets();renderRankings();renderFranchises();renderPurchases();renderAuctionLive();const selected=rankings.find(row=>row.player_id===selectedId);if(selected)choosePlayer(selected.player_id,selected.player_name,selected.dynamic_bid??selected.suggested_auction_value,false);else clearAuctionPlayerSelection()}
async function loadAdminNominationOrder(leagueId){const panel=document.querySelector('#admin-nomination-panel');if(!panel||!leagueId)return;if(adminNominationLeagueId!==leagueId)adminNominationState=null;adminNominationLeagueId=leagueId;const data=await api(`/api/auction/state?league_id=${encodeURIComponent(leagueId)}`);adminNominationState=data.nomination;panel.hidden=false;renderAdminNominationOrder()}
function renderAdminNominationOrder(){const state=adminNominationState,board=document.querySelector('#admin-nomination-board'),status=document.querySelector('#admin-nomination-status');if(!state||!board||!status)return;const direction=state.direction==='reverse'?'right to left':'left to right',progress=state.overall_pick?`Round <strong>${state.auction_round}</strong> · Overall pick <strong>${state.overall_pick}</strong> of ${state.total_capacity} · Auction purchase ${state.auction_pick} · ${state.filled_slots} rostered`:state.total_capacity?`Auction complete · ${state.filled_slots} of ${state.total_capacity} roster spots filled`:'No roster capacity configured';status.innerHTML=state.current_franchise_name?`${progress}<br>${direction} · <strong>${escapeHtml(state.current_franchise_name)}</strong> is current · <strong>${escapeHtml(state.next_franchise_name||'—')}</strong> is next`:state.all_complete?progress:'No franchises are available for nomination order.';board.innerHTML=(state.order||[]).map((team,index)=>{const classes=[team.is_complete?'complete':'',team.is_current?'current':'',team.is_next?'next':''].filter(Boolean).join(' '),badges=team.is_complete?'<span class="nomination-badge current">Finished</span>':`${team.is_current?'<span class="nomination-badge current">Current</span>':''}${team.is_next?'<span class="nomination-badge next">Next</span>':''}`;return`<li class="nomination-team ${classes}" draggable="true" data-order-index="${index}" ondragstart="startNominationDrag(event,${index})" ondragover="overNominationDrag(event)" ondrop="dropNominationTeam(event,${index})" ondragend="endNominationDrag()"><label class="nomination-position" title="Edit order for ${escapeHtml(team.franchise_name)}"><span class="sr-only">Order for ${escapeHtml(team.franchise_name)}</span><input type="number" min="1" max="${state.order.length}" value="${index+1}" draggable="false" onchange="setNominationPosition(${index},this.value)" onclick="event.stopPropagation()"></label><strong>${escapeHtml(team.franchise_name)}</strong><span class="nomination-drag" aria-hidden="true" title="Drag to reorder">⋮⋮</span><span class="nomination-badges">${badges}</span></li>`}).join('')||'<li class="nomination-team">No franchises synchronized.</li>'}
async function saveNominationOrder(franchiseIds){try{adminNominationState=await api(`/api/auction/nomination-order?league_id=${encodeURIComponent(adminNominationLeagueId)}`,{method:'PUT',body:JSON.stringify({franchise_ids:franchiseIds})});renderAdminNominationOrder();toast('Nomination order saved · tracker restarted at the first team')}catch(error){toast(error.message,true)}}
function confirmNominationOrderChange(){return (adminNominationState?.cursor||0)<=0||confirm('Changing the team order restarts nominations at the first team. Continue?')}
async function setNominationPosition(index,value){const order=(adminNominationState?.order||[]).map(team=>team.franchise_id),target=Math.max(0,Math.min(order.length-1,Number.parseInt(value,10)-1));if(!Number.isInteger(target)||target===index){renderAdminNominationOrder();return}if(!confirmNominationOrderChange()){renderAdminNominationOrder();return}const [team]=order.splice(index,1);order.splice(target,0,team);await saveNominationOrder(order)}
function startNominationDrag(event,index){adminNominationDragIndex=index;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(index));event.currentTarget.classList.add('dragging')}
function overNominationDrag(event){if(adminNominationDragIndex===null)return;event.preventDefault();event.dataTransfer.dropEffect='move'}
async function dropNominationTeam(event,target){event.preventDefault();const source=adminNominationDragIndex;endNominationDrag();if(source===null||source===target)return;if(!confirmNominationOrderChange()){renderAdminNominationOrder();return}const order=(adminNominationState?.order||[]).map(team=>team.franchise_id),[team]=order.splice(source,1);order.splice(target,0,team);await saveNominationOrder(order)}
function endNominationDrag(){adminNominationDragIndex=null;document.querySelectorAll('.nomination-team.dragging').forEach(item=>item.classList.remove('dragging'))}
async function randomizeNominationOrder(){if(!adminNominationLeagueId)return toast('Configure and synchronize the auction league first',true);if(!confirm('Randomize every team and restart nominations at the first team?'))return;try{adminNominationState=await api(`/api/auction/nomination-order/randomize?league_id=${encodeURIComponent(adminNominationLeagueId)}`,{method:'POST'});renderAdminNominationOrder();toast('Teams randomized · tracker restarted at the first team')}catch(error){toast(error.message,true)}}
async function resetAuctionAdmin(){if(!adminNominationLeagueId)return toast('Configure and synchronize the auction league first',true);if(prompt('Type RESET to remove every locally recorded auction purchase and turn live mode off.')!=='RESET')return;try{const result=await api(`/api/auction/reset?league_id=${encodeURIComponent(adminNominationLeagueId)}`,{method:'POST'});adminNominationState=result.nomination;renderAdminNominationOrder();toast(`Auction reset · ${result.reset_count} local purchase${result.reset_count===1?'':'s'} removed`)}catch(error){toast(error.message,true)}}
function renderBudgets(){const nomination=auctionState.nomination||{},orderIds=(nomination.order||[]).map(team=>team.franchise_id),byId=new Map(auctionState.franchises.map(team=>[team.franchise_id,team])),ordered=orderIds.map(id=>byId.get(id)).filter(Boolean);auctionState.franchises.forEach(team=>{if(!orderIds.includes(team.franchise_id))ordered.push(team)});document.querySelector('#budget-grid').innerHTML=ordered.map((team,index)=>{const complete=Number(team.slots_remaining)<=0,current=!complete&&team.franchise_id===nomination.current_franchise_id,next=!complete&&team.franchise_id===nomination.next_franchise_id,classes=`${complete?'auction-complete':''} ${current?'current-nominator':''} ${next?'next-nominator':''}`,badges=complete?'<span class="budget-turn finished">Finished</span>':`${current?'<span class="budget-turn current">Nominating now</span>':''}${next?'<span class="budget-turn next">Up next</span>':''}`;return`<article class="budget ${classes}"><div class="budget-heading"><h3><span>${index+1}.</span> ${escapeHtml(team.name)}</h3><span class="budget-turns">${badges}</span></div><dl><dt>Players</dt><dd>${team.slots_used} / ${team.roster_slots}</dd><dt>Spent</dt><dd>${money(team.spent)}</dd><dt>Remaining</dt><dd>${money(team.remaining)}</dd><dt>Maximum bid</dt><dd>${money(team.maximum_bid)}</dd></dl></article>`}).join('')}
function sortAuction(key){auctionDirection=auctionSort===key&&auctionDirection==='asc'?'desc':'asc';auctionSort=key;renderRankings()}
function renderRankings(){const value=id=>document.querySelector(id)?.value||'';const search=value('#player-search').toLowerCase(),position=value('#position-filter'),columnName=value('#auction-name-filter').toLowerCase(),columnPosition=value('#auction-position-filter'),maxRank=Number(value('#auction-rank-filter'))||null,tier=Number(value('#auction-tier-filter'))||null,selectedId=value('#sale-player-id');const filtered=rankings.filter(row=>(!search||row.player_name.toLowerCase().includes(search))&&(!position||row.position===position)&&(!columnName||row.player_name.toLowerCase().includes(columnName))&&(!columnPosition||row.position===columnPosition)&&(!maxRank||Number(row.overall_rank)<=maxRank)&&(!tier||Number(row.tier)===tier));filtered.sort((a,b)=>{const av=a[auctionSort]??'',bv=b[auctionSort]??'';const compared=auctionSort==='player_name'||auctionSort==='position'?String(av).localeCompare(String(bv)):Number(av||Number.MAX_SAFE_INTEGER)-Number(bv||Number.MAX_SAFE_INTEGER);return auctionDirection==='asc'?compared:-compared});document.querySelector('#ranking-body').innerHTML=filtered.slice(0,300).map(row=>`<tr class="auction-player-row ${row.player_id===selectedId?'selected':''}" data-player-id="${escapeHtml(row.player_id)}" role="button" tabindex="0" aria-selected="${row.player_id===selectedId}" onclick="chooseAuctionRow(event,this)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}"><td>${row.overall_rank}</td><td onclick="event.stopPropagation()">${tierEditor(row)}</td><td><a class="player-name-link" href="${profileHref(row)}" onclick="event.stopPropagation()"><strong>${escapeHtml(row.player_name)}</strong></a><br><small>${escapeHtml(row.nfl_team||'FA')}</small> ${playerFlags(row)}</td><td>${escapeHtml(row.position)}</td><td>${row.projected_points==null?'—':Number(row.projected_points).toFixed(2)}</td><td><strong>${money(row.suggested_auction_value)}</strong></td><td class="dynamic-bid-cell"><strong>${money(row.dynamic_bid)}</strong></td><td><strong>${money(row.max_recommended_bid)}</strong></td></tr>`).join('')||'<tr><td colspan="8">No draftable players match.</td></tr>'}
function renderFranchises(){const select=document.querySelector('#sale-franchise'),selected=select.value,openTeams=auctionState.franchises.filter(team=>Number(team.slots_remaining)>0);select.innerHTML='<option value="">Select a franchise</option>'+auctionState.franchises.map(team=>{const complete=Number(team.slots_remaining)<=0;return`<option value="${escapeHtml(team.franchise_id)}" ${complete?'disabled':''}>${escapeHtml(team.name)} · ${complete?'Finished':`max ${money(team.maximum_bid)}`}</option>`}).join('');if(openTeams.some(team=>team.franchise_id===selected))select.value=selected;document.querySelector('#auction-franchise-options').innerHTML=openTeams.map(team=>`<option value="${escapeHtml(team.name)}"></option>`).join('')}
