function clearAuctionPlayerSelection(){document.querySelector('#sale-player-id').value='';document.querySelector('#sale-amount').value='';document.querySelector('#sale-player-match').textContent='Choose a player from the table or type a matching name.';document.querySelectorAll('.auction-player-row.selected').forEach(row=>{row.classList.remove('selected');row.setAttribute('aria-selected','false')})}
function matchSalePlayer(allowUnique){const input=document.querySelector('#sale-player-name'),needle=input.value.trim().toLowerCase();const exact=rankings.find(row=>row.player_name.toLowerCase()===needle),partial=rankings.filter(row=>row.player_name.toLowerCase().includes(needle));const match=exact||(allowUnique&&partial.length===1?partial[0]:null);if(match)return choosePlayer(match.player_id,match.player_name,match.dynamic_bid??match.suggested_auction_value,false);clearAuctionPlayerSelection();document.querySelector('#sale-player-match').textContent=needle?(partial.length?'Keep typing or choose a suggestion.':'No available player matches that name.'):'Choose a player from the table or type a matching name.'}
