async function saveSnapshot(){try{const result=await api(`/api/leagues/${encodeURIComponent(SELECTED_LEAGUE_ID)}/cheat-sheet/recalculate`,{method:'POST',body:JSON.stringify({name:'Saved board'})});toast(`Saved snapshot ${result.snapshot_id}`)}catch(error){toast(error.message,true)}}
