    const options=franchises.map(x=>`<option value="${escapeHtml(x.franchise_id)}">${escapeHtml(x.name)}</option>`).join(''),chosen=previewTeam||state.war_room?.franchise_id||'';
    franchise.innerHTML='<option value="">No franchise selected</option>'+options;franchise.value=chosen;
