    renderDraftPlayers();renderWarRoom(state.war_room,state.intelligence);renderDraftIntelligence(state.intelligence);renderDraftRecommendations(state.intelligence?.recommendations||[],state.war_room);
    document.querySelector('#draft-queue').innerHTML=state.queue.map(x=>`<li><strong>${escapeHtml(x.player_name)}</strong> · ${escapeHtml(x.position)}</li>`).join('')||'<li>Queue players from the board.</li>';
    const recent=[...state.draft_order].filter(x=>x.completed).reverse().slice(0,18);document.querySelector('#draft-picks').innerHTML=recent.map(x=>`<li><strong>${x.overall_pick}. ${escapeHtml(x.player_name||x.player_id||'Recorded pick')}</strong><br><small>${escapeHtml(x.franchise_name||'Franchise unknown')} · ${escapeHtml(x.position||'position unavailable')}</small></li>`).join('')||'<li>No real picks recorded.</li>';
    document.querySelector('#tier-counts').innerHTML=Object.entries(state.tier_counts).map(([key,count])=>`<span>${escapeHtml(key)} <strong>${count}</strong></span>`).join('');
