function renderDraftIntelligence(intelligence){const target=document.querySelector('#draft-intelligence-strip');if(!target)return;const run=intelligence?.position_runs?.[0],cliff=intelligence?.tier_cliffs?.[0],pick=intelligence?.pick_values?.[0],recommendation=intelligence?.recommendations?.[0],survival=recommendation?.survival;const cards=[run?['Position run',`${run.position} rush`,run.label,'alert']:['Position run','Board is balanced','No position has taken 3 of the last 6 picks.','calm'],cliff?['Tier pressure',`${cliff.remaining} ${cliff.position}${cliff.remaining===1?'':'s'} left`,cliff.next_tier?`Tier ${cliff.tier} before Tier ${cliff.next_tier}${cliff.rank_gap?` · ${cliff.rank_gap}-rank drop`:''}`:`Last ranked Tier ${cliff.tier} options`,'alert']:['Tier pressure','No immediate cliff','Every leading position tier has more than three players left.','calm'],pick?['Last-pick value',pick.label,`${pick.player_name} at #${pick.overall_pick} vs ${pick.basis} ${pick.basis_rank}`,(pick.label.includes('Reach')||pick.label.includes('reach'))?'alert':'good']:['Last-pick value','Waiting for a pick','Value/reach appears after a ranked player is selected.','calm'],survival?['Wait-or-take signal',`${survival.chance}% to survive`,`${recommendation.player_name} to pick #${survival.target_pick} · heuristic only`,survival.chance<40?'alert':survival.chance>70?'good':'calm']:['Wait-or-take signal','Select your team','A survival estimate needs your upcoming MFL pick.','calm']];target.innerHTML=cards.map(([label,title,copy,tone])=>`<article class="draft-intel-card ${tone}"><span>${escapeHtml(label)}</span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(copy)}</small></article>`).join('')}
