async function loadRecommendations(){const franchise=document.querySelector('#draft-franchise').value,query=new URLSearchParams({league_id:SELECTED_LEAGUE_ID});if(franchise)query.set('franchise_id',franchise);try{const result=await api(`/api/draft/intelligence?${query}`);if(draftStateData){draftStateData.war_room=result.war_room;draftStateData.intelligence=result.intelligence}renderWarRoom(result.war_room,result.intelligence);renderDraftIntelligence(result.intelligence);renderDraftRecommendations(result.intelligence?.recommendations||[],result.war_room)}catch(error){toast(error.message,true)}}
