function renderTeamDraftBoard(state){const target=document.querySelector('#team-draft-board');if(!target)return;const order=liveDraftBoardOrder(state);if(!order.length){target.innerHTML='<div class="live-board-empty"><strong>No MFL draft order is loaded.</strong><span>Open the Draft Room and use “Sync MFL picks” first.</span></div>';return}const teams=[],seen=new Set();order.forEach(slot=>{const id=slot.franchise_id||slot.franchise_name;if(id&&!seen.has(id)){seen.add(id);teams.push({id,name:slot.franchise_name||id})}});const teamCount=Math.max(teams.length,1),normalized=order.map(slot=>({...slot,_round:Number(slot.round)||Math.ceil(Number(slot.overall_pick||1)/teamCount)})),rounds=[...new Set(normalized.map(slot=>slot._round))].sort((a,b)=>a-b),current=state.current_drafter?.overall_pick,currentTeam=state.current_drafter?.franchise_id;let html='<div class="team-draft-corner">Round</div>'+teams.map(team=>`<div class="team-draft-heading ${team.id===currentTeam?'current':''}"><strong>${escapeHtml(team.name)}</strong><span>${team.id===currentTeam?'On the clock':'Team'}</span></div>`).join('');rounds.forEach(round=>{html+=`<div class="team-draft-round"><strong>${round}</strong><span>Round</span></div>`;teams.forEach(team=>{const slots=normalized.filter(slot=>slot._round===round&&(slot.franchise_id||slot.franchise_name)===team.id);html+=`<div class="team-draft-cell ${team.id===currentTeam?'current-team':''}">${slots.length?slots.map(slot=>draftBoardCard(slot,current)).join(''):'<span class="live-pick-placeholder">No pick</span>'}</div>`})});target.innerHTML=`<div class="team-draft-grid" style="grid-template-columns:58px repeat(${teamCount},minmax(150px,1fr));min-width:${58+teamCount*150}px">${html}</div>`}
