function renderChronologicalDraftBoard(state){const target=document.querySelector('#chronological-draft-board');if(!target)return;const order=liveDraftBoardOrder(state),current=state.current_drafter?.overall_pick;if(!order.length){target.innerHTML='<div class="live-board-empty"><strong>No MFL draft order is loaded.</strong><span>Open the Draft Room and use “Sync MFL picks” first.</span></div>';return}target.innerHTML=order.map(slot=>`<div class="chronological-pick"><span>${escapeHtml(slot.franchise_name||'Unknown team')}</span>${draftBoardCard(slot,current)}</div>`).join('');requestAnimationFrame(scrollLiveDraftBoardToCurrent)}
function renderLiveDraftBoard(){const state=liveDraftBoardState;if(!state)return;const order=liveDraftBoardOrder(state),completed=order.filter(slot=>slot.completed).length,current=state.current_drafter,currentIndex=current?order.findIndex(slot=>Number(slot.overall_pick)===Number(current.overall_pick)):-1,next=currentIndex>=0?order.slice(currentIndex+1).find(slot=>!slot.completed):null,live=Boolean(state.live?.is_live),status=document.querySelector('#live-board-status');document.querySelector('#live-board-current').textContent=current?.franchise_name||'Draft complete';document.querySelector('#live-board-pick').textContent=current?`#${current.overall_pick} · R${current.round||'—'}.${current.pick||'—'}`:'—';document.querySelector('#live-board-next').textContent=next?.franchise_name||'—';document.querySelector('#live-board-progress').textContent=order.length?`${completed} of ${order.length} picks complete · order updated ${shortDate(state.order_fetched_at)}`:'Waiting for the MFL draft order';status.className=`live-board-badge ${live?'live':'offline'}`;status.textContent=live?'Draft live':'Draft paused';renderTeamDraftBoard(state);renderChronologicalDraftBoard(state)}
async function loadLiveDraftBoard(){try{const state=await api(`/api/draft/state?league_id=${encodeURIComponent(window.DRAFT_BOARD_LEAGUE_ID||'')}&include_intelligence=false`),completed=(state.draft_order||[]).filter(slot=>slot.completed).length;if(liveDraftBoardKnownCompleted!==null&&completed>liveDraftBoardKnownCompleted)playDraftSound();liveDraftBoardKnownCompleted=completed;liveDraftBoardState=state;renderLiveDraftBoard()}catch(error){toast(error.message,true)}}
function setLiveDraftBoardView(mode){liveDraftBoardMode=mode==='live'?'live':'team';const team=liveDraftBoardMode==='team';document.querySelector('#team-draft-view').hidden=!team;document.querySelector('#live-draft-view').hidden=team;const teamButton=document.querySelector('#team-board-view-button'),liveButton=document.querySelector('#pick-board-view-button');teamButton.classList.toggle('active',team);teamButton.setAttribute('aria-pressed',String(team));liveButton.classList.toggle('active',!team);liveButton.setAttribute('aria-pressed',String(!team));if(!team)requestAnimationFrame(scrollLiveDraftBoardToCurrent)}
