async function setUserAdmin(username,isAdmin){const action=isAdmin?'give admin access to':'remove admin access from';if(!confirm(`Are you sure you want to ${action} ${username}?`))return;try{await api(`/api/admin/users/${encodeURIComponent(username)}/role`,{method:'PUT',body:JSON.stringify({is_admin:isAdmin})});await loadAdminAccessControls();toast(isAdmin?`${username} is now an admin`:`${username} is no longer an admin`)}catch(error){toast(error.message,true)}}
let adminDraftBoardLeagueId='';
async function configureAdminDraftBoard(leagueId){adminDraftBoardLeagueId=leagueId||'';const link=document.querySelector('#admin-draft-board-link'),button=document.querySelector('#admin-draft-board-launch'),status=document.querySelector('#admin-draft-board-status');if(!link||!button||!status)return;if(!adminDraftBoardLeagueId){link.href='/draft-board';button.disabled=true;status.textContent='Configure the keeper league before launching its board.';return}const url=`/draft-board?league_id=${encodeURIComponent(adminDraftBoardLeagueId)}`;link.href=url;button.disabled=false;try{const state=await api(`/api/draft/state?league_id=${encodeURIComponent(adminDraftBoardLeagueId)}`),live=Boolean(state.live?.is_live),completed=(state.draft_order||[]).filter(slot=>slot.completed).length;status.className=`admin-draft-board-status ${live?'live':'offline'}`;status.textContent=live?`Live now · ${completed} picks complete`:`Paused · ${completed} picks complete`;button.textContent=live?'Open live draft board':'Go live & open board'}catch(error){status.textContent=error.message}}
async function launchLiveDraftBoard(){if(!adminDraftBoardLeagueId)return toast('Configure the keeper league first',true);const button=document.querySelector('#admin-draft-board-launch');button.disabled=true;button.textContent='Launching…';try{await api(`/api/draft/live?league_id=${encodeURIComponent(adminDraftBoardLeagueId)}`,{method:'PUT',body:JSON.stringify({is_live:true})});window.location.assign(`/draft-board?league_id=${encodeURIComponent(adminDraftBoardLeagueId)}`)}catch(error){button.disabled=false;button.textContent='Go live & open board';toast(error.message,true)}}
async function initSettings(){try{const status=await api('/api/setup/status');const form=document.querySelector('#setup-form');for(const key of ['season','keeper_league_id','auction_league_id','user_agent'])form.elements[key].value=status[key]??'';document.querySelector('#security-status').innerHTML=`<dt>Keeper API key</dt><dd>${status.keeper_api_key_configured?'Stored securely':'Not set'}</dd><dt>Auction API key</dt><dd>${status.auction_api_key_configured?'Stored securely':'Not set'}</dd><dt>Commissioner imports</dt><dd>${status.commissioner_configured?'Enabled':'Disabled by default'}</dd>`;form.addEventListener('submit',saveSettings);await Promise.all([loadAdminAccessControls(),configureAdminDraftBoard(status.keeper_league_id)]);if(status.auction_league_id)await loadAdminNominationOrder(status.auction_league_id)}catch(error){toast(error.message,true)}}
async function saveSettings(event){event.preventDefault();const raw=Object.fromEntries(new FormData(event.target));raw.season=Number(raw.season);raw.keeper_api_key=raw.keeper_api_key||null;raw.auction_api_key=raw.auction_api_key||null;try{await api('/api/setup/leagues',{method:'PUT',body:JSON.stringify(raw)});toast('Settings saved securely');await initSettings()}catch(error){toast(error.message,true)}}
async function testLeague(role){const form=document.querySelector('#setup-form');const payload={season:Number(form.elements.season.value),league_id:form.elements[`${role}_league_id`].value,api_key:form.elements[`${role}_api_key`].value||null};const target=document.querySelector(`#${role}-test`);target.textContent='Testing public and protected access…';try{const result=await api('/api/setup/test-mfl',{method:'POST',body:JSON.stringify(payload)});target.innerHTML=`<strong>${escapeHtml(result.name||'League found')}</strong><br>Host: ${escapeHtml(result.host||'unknown')}<br>Public: ${result.public_access.ok?'working':'unavailable'} · Protected: ${result.protected_access.ok?'working':escapeHtml(result.protected_access.error)}`;target.className=`test-result ${result.public_access.ok?'success':'error'}`}catch(error){target.textContent=error.message;target.className='test-result error'}}

async function initWarnings(){document.querySelector('#warning-category').addEventListener('change',loadWarnings);document.querySelector('#warning-resolved').addEventListener('change',loadWarnings);await loadWarnings()}
async function loadWarnings(){try{const params=new URLSearchParams({league_id:SELECTED_LEAGUE_ID,resolved:document.querySelector('#warning-resolved').value,category:document.querySelector('#warning-category').value});const data=await api(`/api/warnings?${params}`);const category=document.querySelector('#warning-category');if(category.options.length===1)category.insertAdjacentHTML('beforeend',data.categories.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x.replace('_',' '))}</option>`).join(''));document.querySelector('#warning-count').textContent=`${data.pagination.total} warning${data.pagination.total===1?'':'s'}`;document.querySelector('#warning-body').innerHTML=data.items.map(x=>`<tr><td>${escapeHtml(x.source)}</td><td><span class="pill">${escapeHtml(x.category)}</span></td><td class="wrap-cell">${escapeHtml(x.message)}</td><td><code>${escapeHtml(x.code)}</code></td><td>${x.occurrences}</td><td>${shortDate(x.last_seen_at)}</td><td><button onclick="setWarning(${x.id},${!x.resolved})">${x.resolved?'Reopen':'Resolve'}</button></td></tr>`).join('')||'<tr><td colspan="7">No warnings in this view.</td></tr>'}catch(error){toast(error.message,true)}}
async function setWarning(id,resolved){try{await api(`/api/warnings/${id}`,{method:'PATCH',body:JSON.stringify({resolved})});toast(resolved?'Warning resolved':'Warning reopened');await loadWarnings()}catch(error){toast(error.message,true)}}

let scoringRows=[];
async function initScoring(){try{const data=await api(`/api/leagues/${encodeURIComponent(SELECTED_LEAGUE_ID)}/scoring-rules`);scoringRows=data.normalized_rules;document.querySelector('#scoring-summary').innerHTML=`<article><strong>${scoringRows.length}</strong><span>Imported rules</span></article><article><strong>${Object.keys(data.derived_settings).length}</strong><span>Derived settings</span></article><article><strong>${scoringRows.filter(x=>!x.mapped).length}</strong><span>Unmapped rules</span></article><article><strong>${shortDate(data.fetched_at)}</strong><span>Fetched from MFL</span></article>`;document.querySelector('#scoring-raw').textContent=JSON.stringify(data.raw_mfl_response,null,2);document.querySelector('#scoring-search').addEventListener('input',renderScoring);renderScoring()}catch(error){toast(error.message,true)}}
function renderScoring(){const needle=(document.querySelector('#scoring-search').value||'').toLowerCase();const order=positions=>/^QB/.test(positions)?0:/^PK$/i.test(positions)?1:/^DEF$/i.test(positions)?2:3;const rows=scoringRows.filter(x=>`${x.positions} ${x.event} ${x.description}`.toLowerCase().includes(needle)).sort((a,b)=>order(a.positions)-order(b.positions)||String(a.positions).localeCompare(String(b.positions)));let group='';const html=[];for(const x of rows){const normalized=String(x.positions).toUpperCase().replaceAll('|',', ');if(normalized!==group){group=normalized;html.push(`<tr class="rule-group"><th colspan="6">Rules for ${escapeHtml(group)}</th></tr>`)}html.push(`<tr><td>${escapeHtml(group)}</td><td class="wrap-cell">${escapeHtml(x.description||'Description not mapped')} <code>${escapeHtml(x.event)}</code></td><td>${escapeHtml(x.range||'—')}</td><td>${escapeHtml(x.points||'—')}</td><td><span class="status ${x.mapped?'good':'owned'}">${x.mapped?'Mapped':'Needs mapping'}</span></td><td></td></tr>`)}document.querySelector('#scoring-body').innerHTML=html.join('')||'<tr><td colspan="6">No rules match.</td></tr>'}

// User accounts and strategy templates
let accountData=null;
async function initAccount(){try{accountData=await api('/api/account');const available=accountData.available_leagues.filter(x=>!x.connected);document.querySelector('#available-mfl-leagues').innerHTML=available.map(league=>`<article class="league-connect-row" data-connect-league="${escapeHtml(league.id)}"><div><strong>${escapeHtml(league.name)}</strong><small>League ${escapeHtml(league.id)}${league.mfl_franchise_id?` · MFL team ${escapeHtml(league.mfl_franchise_id)} detected`:''}</small></div><select class="connect-league-type" aria-label="League format for ${escapeHtml(league.name)}"><option value="keeper">Snake / keeper draft</option><option value="auction">Auction</option></select><button class="primary" onclick="connectLeague('${escapeHtml(league.id)}')">Add league</button></article>`).join('')||(accountData.available_leagues.length?'<p class="muted">All leagues from your MFL account are already connected.</p>':'<p class="muted">No MFL league list is stored yet. Sign out and back in once to refresh it.</p>');document.querySelector('#account-leagues').innerHTML=accountData.leagues.map(league=>{const setting=league.auction_strategy||{template:'balanced'};return `<article class="card account-league" data-league="${escapeHtml(league.id)}"><span class="pill">${escapeHtml(league.type)}</span><h2>${escapeHtml(league.name)}</h2><label>My franchise<select class="account-franchise"><option value="">Not selected</option>${league.franchises.map(team=>`<option value="${escapeHtml(team.id)}" ${team.id===league.franchise_id?'selected':''}>${escapeHtml(team.name)}</option>`).join('')}</select></label>${league.type==='auction'?`<label>Auction strategy<select class="account-strategy">${Object.entries(accountData.auction_strategies).map(([id,value])=>`<option value="${escapeHtml(id)}" ${id===(setting.template||'balanced')?'selected':''}>${escapeHtml(value.name)}</option>`).join('')}</select></label><p class="strategy-help">${escapeHtml(accountData.auction_strategies[setting.template||'balanced']?.description||'')}</p><label>Custom position order<input class="account-priority" value="${escapeHtml((setting.priority_order||accountData.auction_strategies[setting.template||'balanced'].priority_order).join(', '))}" placeholder="WR, RB, QB, TE, DEF"></label>`:''}<button class="primary" onclick="saveAccountLeague('${escapeHtml(league.id)}')">Save my settings</button></article>`}).join('')||'<article class="card">No synchronized leagues yet. Add one above.</article>'}catch(error){toast(error.message,true)}}
async function connectLeague(leagueId){const row=document.querySelector(`[data-connect-league="${CSS.escape(leagueId)}"]`),button=row.querySelector('button');button.disabled=true;button.textContent='Adding…';try{await api('/api/account/leagues',{method:'POST',body:JSON.stringify({league_id:leagueId,league_type:row.querySelector('.connect-league-type').value})});toast('League added and synchronized');await initAccount()}catch(error){button.disabled=false;button.textContent='Add league';toast(error.message,true)}}
async function saveAccountLeague(leagueId){const card=document.querySelector(`[data-league="${CSS.escape(leagueId)}"]`),template=card.querySelector('.account-strategy')?.value||'balanced',priority=(card.querySelector('.account-priority')?.value||'WR,RB,QB,TE,DEF').split(',').map(x=>x.trim().toUpperCase());try{await api(`/api/account/leagues/${encodeURIComponent(leagueId)}`,{method:'PUT',body:JSON.stringify({franchise_id:card.querySelector('.account-franchise').value||null,auction_strategy:{template,priority_order:priority}})});toast('Your league settings were saved')}catch(error){toast(error.message,true)}}

// Source changes are previewed against shared cached data before they are saved per user.
let sourceSettings={};
let sourcePreviewTimer=null;let sourcePreviewRequest=0;let sourceSaveTimers={};
async function initSources(){try{const rows=await api('/api/sources'),localRankingIds=['espn_ppr_csv','espn_dynasty_csv','fantasypros_redraft_csv','fantasypros_dynasty_csv','fantasysharks_dynasty_csv','pff_rankings_csv'];sourceSettings=Object.fromEntries(rows.map(x=>[x.id,{enabled:x.enabled,weight:Number(x.weight)}]));document.querySelector('#source-grid').innerHTML=rows.map(x=>`<article class="card source-card" data-source="${escapeHtml(x.id)}"><div class="source-head"><span class="pill">${escapeHtml(x.kind)}</span><span class="health ${x.last_error?'bad':'good'}">${x.last_error?'Needs attention':'Ready'}</span></div><h2>${escapeHtml(x.name)}</h2><p>${escapeHtml(x.attribution||'Local data')}</p><dl class="status-list"><dt>License</dt><dd>${escapeHtml(x.license||'—')}</dd><dt>Visibility</dt><dd>${x.visibility==='personal'?'Private to your account':'Shared with all accounts'}</dd><dt>Last success</dt><dd>${shortDate(x.last_success_at)}</dd><dt>Matched rows</dt><dd>${x.received_count??0}</dd><dt>Setting</dt><dd>${x.personalized?'Your saved weight':`Default ${Number(x.default_weight).toFixed(1)}`}</dd><dt>Cache interval</dt><dd>${Math.round(x.cache_ttl_seconds/3600)}h</dd></dl>${x.last_error?`<p class="warning-text">${escapeHtml(x.last_error)}</p>`:''}<div class="source-controls"><label class="source-toggle"><input class="source-enabled" type="checkbox" ${x.enabled?'checked':''} onchange="sourceChanged('${x.id}',true)"> Include in my rankings</label><label class="source-weight-label"><span>Influence <output class="source-weight-value">${Number(x.weight).toFixed(1)}</output></span><input class="source-weight" type="range" min="0" max="10" step=".1" value="${x.weight}" oninput="sourceChanged('${x.id}',false)" onchange="saveSourceCard('${x.id}')"><small>0 = none · 10 = strongest</small></label></div><div class="toolbar"><span class="source-save-state muted">Saved</span>${x.terms_url?`<a href="${escapeHtml(x.terms_url)}" target="_blank" rel="noreferrer">Terms</a>`:'<span class="muted">Local file</span>'}${localRankingIds.includes(x.id)?`<button onclick="showSourceData('${x.id}')">View CSV rows</button>`:''}${['sleeper','nflverse','gng',...localRankingIds].includes(x.id)?`<button onclick="syncOneSource('${x.id}')">Refresh data</button>`:''}</div></article>`).join('');const picker=document.querySelector('#source-preview-league');if(picker)picker.onchange=scheduleSourcePreview;scheduleSourcePreview()}catch(error){toast(error.message,true)}}
function sourceCard(id){return document.querySelector(`[data-source="${CSS.escape(id)}"]`)}
function sourceChanged(id,saveNow){const card=sourceCard(id),weight=Number(card.querySelector('.source-weight').value)||0;card.querySelector('.source-weight-value').value=weight.toFixed(1);sourceSettings[id]={enabled:card.querySelector('.source-enabled').checked,weight};card.querySelector('.source-save-state').textContent='Saving…';scheduleSourcePreview();if(saveNow)saveSourceCard(id);else{clearTimeout(sourceSaveTimers[id]);sourceSaveTimers[id]=setTimeout(()=>saveSourceCard(id),450)}}
function scheduleSourcePreview(){clearTimeout(sourcePreviewTimer);sourcePreviewTimer=setTimeout(previewSourcesLive,160)}
async function previewSourcesLive(){const league=document.querySelector('#source-preview-league')?.value;if(!league)return;const request=++sourcePreviewRequest,status=document.querySelector('#source-preview-status');status.textContent='Recalculating…';try{const result=await api('/api/sources/preview',{method:'POST',body:JSON.stringify({league_id:league,sources:sourceSettings})});if(request!==sourcePreviewRequest)return;const changes=Object.fromEntries(result.movers.map(x=>[`${x.player_name}|${x.position}`,x.change]));document.querySelector('#source-preview').innerHTML=`<div class="table-wrap live-ranking-preview"><table><thead><tr><th>New rank</th><th>Move</th><th>Player</th><th>Position</th><th>Tier</th><th>Sources</th></tr></thead><tbody>${result.top.map(row=>{const change=changes[`${row.player_name}|${row.position}`]||0;return `<tr><td><strong>${row.consensus_rank}</strong></td><td><span class="ranking-movement ${change>0?'up':change<0?'down':''}">${change>0?`▲ ${change}`:change<0?`▼ ${Math.abs(change)}`:'—'}</span></td><td><a class="player-name-link" href="/player/${encodeURIComponent(row.player_id)}?league_id=${encodeURIComponent(league)}">${escapeHtml(row.player_name)}</a></td><td>${escapeHtml(row.position)}</td><td>${row.tier??'—'}</td><td>${row.source_count??0}</td></tr>`}).join('')}</tbody></table></div>`;status.textContent=`Showing ${result.top.length} recalibrated players · changes save automatically`}catch(error){if(request===sourcePreviewRequest){status.textContent='Could not recalculate';document.querySelector('#source-preview').textContent=error.message}}}
async function saveSourceCard(id){clearTimeout(sourceSaveTimers[id]);const card=sourceCard(id),state=card.querySelector('.source-save-state');try{await api(`/api/setup/sources/${encodeURIComponent(id)}`,{method:'PUT',body:JSON.stringify(sourceSettings[id])});state.textContent='Saved automatically'}catch(error){state.textContent='Save failed';toast(error.message,true)}}
async function resetMyRankings(){if(!confirm('Reset every ranking-source slider to its default? Player targets, notes, and manual tiers will stay unchanged.'))return;Object.values(sourceSaveTimers).forEach(clearTimeout);sourceSaveTimers={};try{const result=await api('/api/sources/reset',{method:'POST'});toast(`Ranking sources reset to default${result.reset_count?` · ${result.reset_count} custom setting(s) removed`:''}`);await initSources()}catch(error){toast(error.message,true)}}
let activeSourceDataId=null;
async function showSourceData(id){const panel=document.querySelector('#source-data-panel'),heading=document.querySelector('#source-data-heading'),status=document.querySelector('#source-data-status'),body=document.querySelector('#source-data-body'),printButton=document.querySelector('#source-data-print'),download=document.querySelector('#source-data-download');activeSourceDataId=id;panel.hidden=false;printButton.hidden=true;download.hidden=true;status.textContent='Loading the exact matched CSV rows used by this server…';body.innerHTML='<p class="muted">Loading…</p>';panel.scrollIntoView({behavior:'smooth',block:'start'});try{const result=await api(`/api/sources/${encodeURIComponent(id)}/data`);heading.textContent=result.source_name;status.textContent=`${result.total_count} matched rows stored on this server · showing ${result.returned_count}`;printButton.hidden=false;download.hidden=false;download.href=`/api/sources/${encodeURIComponent(id)}/download.csv`;body.innerHTML=result.rows.length?`<div class="table-wrap source-data-table"><table><thead><tr><th>League</th><th>Player</th><th>Team</th><th>Pos</th><th>Rank</th><th>Pos rank</th><th>Tier</th><th>Auction value</th><th>File</th><th>Loaded</th></tr></thead><tbody>${result.rows.map(row=>{const raw=row.raw||{};return`<tr><td>${escapeHtml(row.league_name||row.league_id||'—')}</td><td><strong>${escapeHtml(raw.player_name||row.player_name)}</strong><small class="subrank">MFL ${escapeHtml(row.player_id)}</small></td><td>${escapeHtml(raw.team||row.nfl_team||'FA')}</td><td>${escapeHtml(raw.position||row.position||'—')}</td><td><strong>${escapeHtml(raw.overall_rank??row.rank_signal??'—')}</strong></td><td>${escapeHtml(raw.position_rank??'—')}</td><td>${escapeHtml(raw.tier??'—')}</td><td>${escapeHtml(raw.auction_value??'—')}</td><td>${escapeHtml(raw.source_file??'—')}</td><td>${shortDate(row.fetched_at)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="notice warning">No local CSV rows are matched yet. Refresh the source after an MFL player sync.</div>'}catch(error){status.textContent='Could not load CSV data';body.innerHTML=`<div class="notice warning">${escapeHtml(error.message)}</div>`}}
function printSourceData(){if(!activeSourceDataId)return;document.body.classList.add('print-source-data');window.addEventListener('afterprint',()=>document.body.classList.remove('print-source-data'),{once:true});window.print()}
function closeSourceData(){document.querySelector('#source-data-panel').hidden=true}

// Rookie, sleeper, and target filters on the cheat sheet.
async function initCheatSheet(){const choices=await api(`/api/players/filters?league_id=${encodeURIComponent(SELECTED_LEAGUE_ID)}`);setSelectOptions('#cheat-position',choices.positions);setSelectOptions('#cheat-column-position',choices.positions,'All');document.querySelector('#cheat-search').addEventListener('input',loadCheat);document.querySelector('#cheat-position').addEventListener('change',loadCheat);document.querySelector('#cheat-availability').addEventListener('change',loadCheat);document.querySelector('#cheat-tag').addEventListener('change',loadCheat);document.querySelectorAll('#cheat-column-name,#cheat-column-position,#cheat-column-tier,#cheat-column-sources').forEach(x=>x.addEventListener('input',renderCheat));document.querySelector('#ranking-form').addEventListener('submit',importRanking);await loadCheat()}
async function loadCheat(){try{const selected=document.querySelector('#cheat-tag')?.value||'',params=new URLSearchParams({search:document.querySelector('#cheat-search').value,position:document.querySelector('#cheat-position').value,availability:document.querySelector('#cheat-availability').value,per_page:'500'});if(selected==='rookie')params.set('rookie','true');else if(selected)params.set('tag',selected);const data=await api(`/api/leagues/${encodeURIComponent(SELECTED_LEAGUE_ID)}/cheat-sheet?${params}`);cheatRows=data.items;renderCheat()}catch(error){toast(error.message,true)}}
function playerFlags(row){const flags=[];if(row.rookie)flags.push('<span class="player-flag rookie">Rookie</span>');if((row.preference?.tags||[]).includes('sleeper'))flags.push('<span class="player-flag sleeper">Sleeper</span>');if(row.injury_status)flags.push(`<span class="player-flag injury">${escapeHtml(row.injury_status)}</span>`);if(row.source_confidence==='low')flags.push('<span class="player-flag limited">Limited sources</span>');return flags.join(' ')}

let comparedPlayers=[];
function comparisonOptionValue(row){return `${row.player_name} — ${row.nfl_team||'FA'} · ${row.position}`}
function resetOptionalComparisonPlayers(){document.querySelectorAll('[data-compare-optional]').forEach(slot=>{slot.hidden=true;slot.querySelector('.compare-player-input').value=''});document.querySelector('#compare-add').hidden=false}
function updateComparisonAddButton(){document.querySelector('#compare-add').hidden=![...document.querySelectorAll('[data-compare-optional]')].some(slot=>slot.hidden)}
function addComparisonPlayer(){const slot=[...document.querySelectorAll('[data-compare-optional]')].find(item=>item.hidden);if(!slot)return;slot.hidden=false;slot.querySelector('.compare-player-input').focus();updateComparisonAddButton()}
function removeComparisonPlayer(button){const slot=button.closest('[data-compare-optional]');slot.querySelector('.compare-player-input').value='';slot.hidden=true;updateComparisonAddButton()}
function openPlayerCompare(){const dialog=document.querySelector('#player-compare'),options=document.querySelector('#compare-player-options');options.innerHTML=cheatRows.map(row=>`<option value="${escapeHtml(comparisonOptionValue(row))}">#${row.consensus_rank} · Tier ${row.tier??'—'}</option>`).join('');resetOptionalComparisonPlayers();dialog.showModal();dialog.querySelector('.compare-player-input').focus()}
function selectedComparisonPlayers(){const selected=[];for(const input of document.querySelectorAll('.compare-player-input')){const value=input.value.trim();if(!value)continue;const exact=cheatRows.find(row=>comparisonOptionValue(row)===value);const named=cheatRows.filter(row=>row.player_name.toLowerCase()===value.toLowerCase());const row=exact||(named.length===1?named[0]:null);if(!row)throw new Error(`Choose “${value}” from the player list`);if(selected.some(item=>item.player_id===row.player_id))throw new Error('Choose each player only once');selected.push(row)}return selected}
function comparisonValue(value,prefix=''){return value==null||value===''?'—':`${prefix}${value}`}
function renderPlayerComparison(){try{const selected=selectedComparisonPlayers();if(selected.length<2)throw new Error('Choose at least two players');comparedPlayers=selected;const metrics=[['NFL team',row=>row.nfl_team||'FA'],['Position',row=>row.position],['Consensus rank',row=>comparisonValue(row.consensus_rank,'#')],['Weekly model rank',row=>comparisonValue(row.league_adjusted_rank,'#')],['Tier',row=>comparisonValue(row.tier)],['Source signals',row=>comparisonValue(row.source_count)],['Value over replacement',row=>comparisonValue(row.value_over_replacement)],['Bye week',row=>comparisonValue(row.bye_week)],['Injury',row=>row.injury_status||'None reported'],['Availability',row=>row.available?'Available':row.rostered_by||'Selected']];if(window.CHEAT_MODE==='auction')metrics.splice(7,0,['Suggested bid',row=>row.suggested_auction_value==null?'—':money(row.suggested_auction_value)],['Dynamic bid',row=>row.dynamic_bid==null?'—':money(row.dynamic_bid)],['Maximum bid',row=>row.max_recommended_bid==null?'—':money(row.max_recommended_bid)]);else metrics.splice(7,0,['Average / median rank',row=>`${comparisonValue(row.average_rank)} / ${comparisonValue(row.median_rank)}`],['Best–worst rank',row=>`${comparisonValue(row.best_rank)}–${comparisonValue(row.worst_rank)}`],['ADP',row=>comparisonValue(row.adp)]);document.querySelector('#player-compare-results').innerHTML=`<div class="table-wrap compare-table"><table><thead><tr><th>Metric</th>${selected.map(row=>`<th><a class="player-name-link" href="${profileHref(row)}">${escapeHtml(row.player_name)}</a></th>`).join('')}</tr></thead><tbody>${metrics.map(([label,read])=>`<tr><th scope="row">${escapeHtml(label)}</th>${selected.map(row=>`<td>${escapeHtml(read(row))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;document.querySelector('#compare-recommendation').innerHTML='<div class="notice">Checking team needs and the live overall board…</div>';document.querySelector('#compare-decision').innerHTML='';document.querySelector('#compare-coin').disabled=false;document.querySelector('#compare-coin').textContent=selected.length===2?'Flip a coin':'Random pick';document.querySelector('#compare-chatgpt').disabled=false;loadComparisonRecommendation()}catch(error){toast(error.message,true)}}
async function loadComparisonRecommendation(){const output=document.querySelector('#compare-recommendation');try{const result=await api(`/api/leagues/${encodeURIComponent(SELECTED_LEAGUE_ID)}/compare/recommendation`,{method:'POST',body:JSON.stringify({player_ids:comparedPlayers.map(row=>row.player_id)})});const winner=result.candidates.find(row=>row.player_id===result.recommended_player_id),team=result.franchise_name||'No team selected';output.innerHTML=`<article class="compare-recommendation-card"><div><span class="pill">DraftDesk recommendation</span><h3>${winner?escapeHtml(winner.player_name):'No available choice'}</h3><p>${escapeHtml(result.reason)}</p><small>${escapeHtml(team)} · Team need plus live overall rank</small></div><ol>${result.candidates.map(row=>`<li class="${row.player_id===result.recommended_player_id?'recommended':''}"><strong>${row.recommendation_rank}. ${escapeHtml(row.player_name)}</strong><span>#${row.overall_rank} overall · ${row.need_slots?`fills ${row.need_slots} open ${escapeHtml(row.position)} slot${row.need_slots===1?'':'s'}`:'no open primary-position need'}${row.available?'':' · unavailable'}</span></li>`).join('')}</ol></article>`}catch(error){output.innerHTML=`<div class="notice warning">Recommendation unavailable: ${escapeHtml(error.message)}</div>`}}
function secureRandomIndex(length){const values=new Uint32Array(1),limit=Math.floor(4294967296/length)*length;do{crypto.getRandomValues(values)}while(values[0]>=limit);return values[0]%length}
function decideComparisonRandomly(){if(comparedPlayers.length<2)return;const winner=comparedPlayers[secureRandomIndex(comparedPlayers.length)],label=comparedPlayers.length===2?'Coin flip':'Random draw';document.querySelector('#compare-decision').innerHTML=`<div class="notice success"><strong>${label}: ${escapeHtml(winner.player_name)}</strong><br><span>This is random—not a ranking recommendation.</span></div>`}
async function askComparisonChatGPT(){if(comparedPlayers.length<2)return;const button=document.querySelector('#compare-chatgpt'),output=document.querySelector('#compare-decision');button.disabled=true;output.innerHTML='<div class="notice">ChatGPT is reviewing the live league metrics…</div>';try{const result=await api(`/api/leagues/${encodeURIComponent(SELECTED_LEAGUE_ID)}/compare/chatgpt`,{method:'POST',body:JSON.stringify({player_ids:comparedPlayers.map(row=>row.player_id)})});output.innerHTML=`<article class="compare-chatgpt-answer"><span class="pill">ChatGPT tie-breaker</span><p>${escapeHtml(result.answer)}</p></article>`}catch(error){output.innerHTML=`<div class="notice warning">${escapeHtml(error.message)}</div>`}finally{button.disabled=false}}

// ADFL has no auction bid limit, so keeper-league roster cards omit it.
async function initRosters(){try{rosterData=await api(`/api/leagues/${encodeURIComponent(SELECTED_LEAGUE_ID)}/rosters`);const isAuction=rosterData.league_type==='auction';document.querySelector('#roster-summary').innerHTML=rosterData.teams.map(team=>`<article class="card roster-card"><span class="pill">${team.slots_used}/${team.roster_slots} spots</span><h2><a href="/franchises/${encodeURIComponent(team.franchise_id)}?league_id=${encodeURIComponent(SELECTED_LEAGUE_ID)}">${escapeHtml(team.name)}</a></h2><p class="position-line">${Object.entries(team.position_counts).map(([p,n])=>`${p} ${n}`).join(' · ')||'No players'}</p><dl><div><dt>Open</dt><dd>${team.slots_remaining}</dd></div><div><dt>Strength</dt><dd>${team.roster_strength}</dd></div>${isAuction?`<div><dt>Max bid</dt><dd>${money(team.maximum_bid)}</dd></div>`:''}</dl></article>`).join('');renderRosterTable();document.querySelectorAll('#roster-search,#roster-owner-filter,#roster-player-filter,#roster-position-filter,#roster-team-filter,#roster-status-filter,#roster-keeper-filter').forEach(x=>x.addEventListener('input',renderRosterTable))}catch(error){toast(error.message,true)}}

// Live auction viewers poll a lightweight revision and refresh when an admin changes state.
let auctionRevision=null;
async function initAuction(){try{await refreshAuction();auctionRevision=auctionState.live?.revision??0;renderAuctionLive()}catch(error){toast(error.message,true)}document.querySelectorAll('#player-search,#position-filter,#auction-rank-filter,#auction-tier-filter,#auction-name-filter,#auction-position-filter').forEach(x=>x?.addEventListener('input',renderRankings));const salePlayer=document.querySelector('#sale-player-name');salePlayer?.addEventListener('input',()=>{clearTimeout(saleMatchTimer);matchSalePlayer(false);saleMatchTimer=setTimeout(()=>matchSalePlayer(true),250)});salePlayer?.addEventListener('blur',()=>matchSalePlayer(true));const saleFranchise=document.querySelector('#sale-franchise-name');saleFranchise?.addEventListener('input',()=>matchSaleFranchise(false));saleFranchise?.addEventListener('blur',()=>matchSaleFranchise(true));document.querySelector('#sale-franchise')?.addEventListener('change',syncSaleFranchiseName);document.querySelector('#sale-form')?.addEventListener('submit',saveSale);window.setInterval(pollAuction,3000)}
function renderAuctionLive(){const live=auctionState.live||{},nomination=auctionState.nomination||{},status=document.querySelector('#auction-live-status'),button=document.querySelector('#auction-live-button'),pick=document.querySelector('#auction-pick-status');if(status){status.className=`auction-live-badge ${live.is_live?'live':'offline'}`;status.textContent=live.is_live?'Auction is live':'Auction is not live'}if(button)button.textContent=live.is_live?'End live auction':'Go live';if(pick)pick.innerHTML=nomination.overall_pick?`<span>Round ${nomination.auction_round} · Current pick</span><strong>${nomination.overall_pick} of ${nomination.total_capacity}</strong><small>Auction purchase ${nomination.auction_pick} · ${nomination.filled_slots} rostered · ${nomination.remaining_slots} left</small>`:`<span>Auction progress</span><strong>${nomination.filled_slots||0} of ${nomination.total_capacity||0}</strong><small>${nomination.total_capacity?'Every roster spot is filled':'Roster capacity is not configured'}</small>`}
async function pollAuction(){if(document.visibilityState!=='visible')return;try{const state=await api(`/api/auction/state?league_id=${encodeURIComponent(AUCTION_LEAGUE_ID)}`);if(auctionRevision!==state.live.revision){auctionRevision=state.live.revision;await refreshAuction();renderAuctionLive()}}catch{}}
async function toggleAuctionLive(){try{const next=!(auctionState.live?.is_live);await api(`/api/auction/live?league_id=${encodeURIComponent(AUCTION_LEAGUE_ID)}`,{method:'PUT',body:JSON.stringify({is_live:next})});await refreshAuction();auctionRevision=auctionState.live.revision;renderAuctionLive();toast(next?'Auction is live':'Auction ended')}catch(error){toast(error.message,true)}}
function renderPurchases(){const purchases=auctionState.purchases||[],latest=purchases[0],latestTarget=document.querySelector('#auction-last-purchase');if(latestTarget)latestTarget.innerHTML=latest?`<span>${escapeHtml(latest.player_name)}</span>${latest.player_team?` <small>(${escapeHtml(latest.player_team)})</small>`:''} · <strong>${money(latest.amount)}</strong> to ${escapeHtml(latest.franchise_name)}`:'No purchases recorded yet';document.querySelector('#recent-purchases').innerHTML=purchases.slice(0,14).map(row=>`<li><strong>${escapeHtml(row.player_name)}</strong>${row.player_team?` <small>(${escapeHtml(row.player_team)})</small>`:''} → <strong>${escapeHtml(row.franchise_name)}</strong> for ${money(row.amount)}${window.IS_AUCTION_ADMIN?`<div class="purchase-actions"><button onclick="changeAuctionPurchasePlayer('${row.id}')">Change player</button><button onclick="editAuctionBid('${row.id}')">Correct bid</button><button onclick="changeAuctionPurchaseTeam('${row.id}')">Change team</button><button onclick="removeAuctionPurchase('${row.id}')">Remove</button></div>`:''}</li>`).join('')||'<li>No purchases yet.</li>'}
async function changeAuctionPurchasePlayer(id){const row=auctionState.purchases.find(x=>x.id===id);if(!row)return;const answer=prompt(`Replace ${row.player_name} with which available player?`);if(!answer)return;const needle=answer.trim().toLowerCase(),exact=rankings.find(player=>player.player_name.toLowerCase()===needle),partial=rankings.filter(player=>player.player_name.toLowerCase().includes(needle)),player=exact||(partial.length===1?partial[0]:null);if(!player)return toast('Type one matching available player name',true);try{await api(`/api/auction/purchases/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({player_id:player.player_id,version:row.version})});toast(`${row.player_name} replaced with ${player.player_name}`);await refreshAuction()}catch(error){toast(error.message,true)}}
async function editAuctionBid(id){const row=auctionState.purchases.find(x=>x.id===id);if(!row)return;const amount=prompt(`Correct winning bid for ${row.player_name}`,row.amount);if(!amount)return;try{await api(`/api/auction/purchases/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({amount:Number(amount),version:row.version})});toast('Winning bid corrected');await refreshAuction()}catch(error){toast(error.message,true)}}
async function changeAuctionPurchaseTeam(id){const row=auctionState.purchases.find(x=>x.id===id);if(!row)return;const answer=prompt(`Move ${row.player_name} to which team?`,row.franchise_name);if(!answer)return;const needle=answer.trim().toLowerCase(),exact=auctionState.franchises.find(team=>team.name.toLowerCase()===needle),partial=auctionState.franchises.filter(team=>team.name.toLowerCase().includes(needle)),team=exact||(partial.length===1?partial[0]:null);if(!team)return toast('Type one matching franchise name',true);try{await api(`/api/auction/purchases/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({franchise_id:team.franchise_id,version:row.version})});toast(`Purchase moved to ${team.name}`);await refreshAuction()}catch(error){toast(error.message,true)}}
async function removeAuctionPurchase(id){if(!confirm('Remove this purchase? The player will become available and the current pick and nominator will recalculate automatically.'))return;try{await api(`/api/auction/purchases/${encodeURIComponent(id)}`,{method:'DELETE'});toast('Purchase removed · pick and nomination order recalculated');await refreshAuction()}catch(error){toast(error.message,true)}}
let mflImportPreview=null;
async function openMflImportPreview(){const dialog=document.querySelector('#mfl-import-dialog');dialog.showModal();document.querySelector('#mfl-import-summary').textContent='Building a fresh preview…';document.querySelector('#mfl-import-confirm').value='';try{mflImportPreview=await api(`/api/auction/import-preview?league_id=${encodeURIComponent(AUCTION_LEAGUE_ID)}`);document.querySelector('#mfl-import-summary').innerHTML=`<p><strong>${mflImportPreview.purchase_count}</strong> reviewed purchase${mflImportPreview.purchase_count===1?'':'s'} will be included.</p>${mflImportPreview.imports_enabled?'':'<p class="notice warning">Commissioner imports are disabled in Admin settings.</p>'}`;document.querySelector('#mfl-import-xml').textContent=mflImportPreview.xml;document.querySelector('#mfl-import-submit').disabled=!mflImportPreview.imports_enabled}catch(error){document.querySelector('#mfl-import-summary').innerHTML=`<p class="notice warning">${escapeHtml(error.message)}</p>`;document.querySelector('#mfl-import-submit').disabled=true}}
async function submitMflImport(){if(!mflImportPreview)return toast('Preview the import first',true);if(document.querySelector('#mfl-import-confirm').value.trim()!=='IMPORT')return toast('Type IMPORT to confirm',true);if(!confirm(`Send ${mflImportPreview.purchase_count} reviewed auction result(s) to MFL now?`))return;const button=document.querySelector('#mfl-import-submit');button.disabled=true;try{await api('/api/auction/push-to-mfl',{method:'POST',body:JSON.stringify({league_id:AUCTION_LEAGUE_ID,confirmation_token:mflImportPreview.confirmation_token,clear:document.querySelector('#mfl-import-clear').checked,overwrite:document.querySelector('#mfl-import-overwrite').checked})});document.querySelector('#mfl-import-dialog').close();toast('MFL auction results imported successfully')}catch(error){toast(error.message,true);button.disabled=false}}

function depthChartGroup(position){const value=String(position||'').toUpperCase(),special=new Set(['PK','K','P','H','PR','KR','LS']),offense=new Set(['QB','RB','FB','WR','LWR','RWR','SWR','TE','LT','LG','C','RG','RT','OL']);if(special.has(value))return'Special Teams';if(offense.has(value)||value.endsWith('WR'))return'Offense';return'Defense'}
function depthChartPlayer(row){const league=window.SELECTED_LEAGUE_ID?`?league_id=${encodeURIComponent(window.SELECTED_LEAGUE_ID)}`:'',flags=[row.rookie?'Rookie':'',row.injury_status||''].filter(Boolean).map(flag=>`<span class="player-flag">${escapeHtml(flag)}</span>`).join('');return`<a class="depth-player" href="/player/${encodeURIComponent(row.player_id)}${league}"><strong>${escapeHtml(row.player_name)}</strong><small>${escapeHtml(row.position||row.depth_position)}${flags?` · ${flags}`:''}</small></a>`}
function renderDepthCharts(data){
  const select=document.querySelector('#depth-team'),selected=data.selected_team,status=document.querySelector('#depth-chart-status')
  select.innerHTML=data.teams.map(team=>`<option value="${escapeHtml(team.code)}">${escapeHtml(team.name)}${team.player_count?` · ${team.player_count}`:''}</option>`).join('')
  select.value=selected.code
  document.querySelector('#depth-espn-link').href=selected.espn_url
  const orderWarning=data.players.length&&!data.ordered_player_count?' Cached data identifies positions but not starter order; refresh nflverse/Sleeper or use ESPN for the published order.':''
  status.className=`notice${orderWarning?' warning':''}`
  status.innerHTML=`Showing <strong>${escapeHtml(selected.name)}</strong> · ${data.players.length} cached players. ${escapeHtml(data.source_note)}${escapeHtml(orderWarning)}`
  const groups={Offense:new Map(),Defense:new Map(),'Special Teams':new Map()}
  data.players.forEach(row=>{const group=groups[depthChartGroup(row.depth_position)],position=row.depth_position;if(!group.has(position))group.set(position,[]);group.get(position).push(row)})
  document.querySelector('#depth-chart-groups').innerHTML=Object.entries(groups).filter(([,positions])=>positions.size).map(([groupName,positions])=>`<article class="panel depth-chart-panel"><div class="panel-head"><h2>${escapeHtml(groupName)}</h2><span class="pill">${[...positions.values()].reduce((total,rows)=>total+rows.length,0)} players</span></div><div class="table-wrap"><table><thead><tr><th>Position</th><th>Starter</th><th>Second</th><th>Third</th><th>Fourth+</th><th>Order unavailable</th></tr></thead><tbody>${[...positions.entries()].map(([position,rows])=>`<tr><th scope="row">${escapeHtml(position)}</th>${[1,2,3,4,null].map(order=>`<td>${rows.filter(row=>order===null?row.depth_order==null:order===4?row.depth_order>=4:row.depth_order===order).map(depthChartPlayer).join('')||'<span class="muted">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></article>`).join('')||'<article class="panel"><h2>No cached depth chart</h2><p>Refresh nflverse and Sleeper under Sources, or use the ESPN link for the latest published chart.</p></article>'
}
async function loadDepthChart(team){const data=await api(`/api/depth-charts${team?`?team=${encodeURIComponent(team)}`:''}`);renderDepthCharts(data);localStorage.setItem('draftdesk:depth-team',data.selected_team.code)}
async function initDepthCharts(){const select=document.querySelector('#depth-team');select.addEventListener('change',()=>loadDepthChart(select.value).catch(error=>toast(error.message,true)));try{await loadDepthChart(localStorage.getItem('draftdesk:depth-team')||'')}catch(error){toast(error.message,true);document.querySelector('#depth-chart-groups').innerHTML=`<article class="notice warning">${escapeHtml(error.message)}</article>`}}
async function initPowerRankings(){if(!SELECTED_LEAGUE_ID)return toast('Select a league first',true);try{const data=await api(`/api/leagues/${encodeURIComponent(SELECTED_LEAGUE_ID)}/power-rankings`);document.querySelector('#power-method').textContent=data.methodology;document.querySelector('#power-rankings').innerHTML=data.rankings.map(team=>`<article class="panel power-ranking-card"><div class="power-rank"><span>#</span><strong>${team.rank}</strong></div><div><p class="eyebrow">POWER SCORE ${team.power_score}</p><h2><a href="/franchises/${encodeURIComponent(team.franchise_id)}?league_id=${encodeURIComponent(SELECTED_LEAGUE_ID)}">${escapeHtml(team.franchise_name)}</a></h2><p>${escapeHtml(team.summary)}</p><p class="muted">${team.roster_size} players · starter value ${team.starter_value} · depth ${team.depth_value}</p></div></article>`).join('')||'<article class="panel">No rostered teams are available.</article>'}catch(error){toast(error.message,true)}}
async function judgePowerRankings(){const button=document.querySelector('#power-chatgpt');button.disabled=true;button.textContent='ChatGPT is judging…';try{const data=await api(`/api/leagues/${encodeURIComponent(SELECTED_LEAGUE_ID)}/power-rankings/chatgpt`,{method:'POST'});document.querySelector('#power-judge-model').textContent=`Judged with ${data.model}`;document.querySelector('#power-judge-output').innerHTML=`<p>${escapeHtml(data.analysis).replaceAll('\n','<br>')}</p>`;document.querySelector('#power-judge-dialog').showModal()}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='Ask ChatGPT to judge'}}

// League-aware chat persists for this browser session until the user starts a new chat.
let assistantHistory=[];let assistantLeague=null;let assistantSending=false;
function currentAssistantLeague(){return typeof SELECTED_LEAGUE_ID!=='undefined'&&SELECTED_LEAGUE_ID?SELECTED_LEAGUE_ID:(typeof AUCTION_LEAGUE_ID!=='undefined'&&AUCTION_LEAGUE_ID?AUCTION_LEAGUE_ID:document.querySelector('.league-picker select')?.value||window.DRAFTDESK_CHAT_CONTEXT?.league_id||null)}
function assistantStorageKey(league){return `draftdesk:chat:${window.DRAFTDESK_CHAT_CONTEXT?.username||'user'}:${league}`}
function loadAssistantHistory(league){try{const saved=JSON.parse(sessionStorage.getItem(assistantStorageKey(league))||'[]');return Array.isArray(saved)?saved.filter(x=>['user','assistant'].includes(x.role)&&typeof x.content==='string').slice(-30):[]}catch{return []}}
function saveAssistantHistory(){if(assistantLeague)sessionStorage.setItem(assistantStorageKey(assistantLeague),JSON.stringify(assistantHistory.slice(-30)))}
function assistantWelcome(){return `<div class="assistant-welcome"><div class="assistant-avatar">D</div><h3>How can I help with your draft?</h3><p>I remember this conversation until you select <strong>New chat</strong>.</p></div>`}
function renderAssistantHistory(){const box=document.querySelector('#assistant-messages');box.innerHTML=assistantHistory.length?assistantHistory.map(x=>`<article class="assistant-message ${x.role==='user'?'assistant-user':'assistant-answer'}"><span>${x.role==='user'?'You':'Draft Advisor'}</span><p>${escapeHtml(x.content)}</p></article>`).join(''):assistantWelcome();box.scrollTop=box.scrollHeight}
async function openAssistant(){const league=currentAssistantLeague();if(!league)return toast('Choose a league first',true);try{const status=await api(`/api/assistant/status?league_id=${encodeURIComponent(league)}`);if(!status.enabled)return toast('Add OPENAI_API_KEY in Railway to enable Draft Advisor',true);assistantLeague=league;assistantHistory=loadAssistantHistory(league);document.querySelector('#assistant-context').textContent=`${status.league_name||'Selected league'} · ${String(status.league_type||'').toUpperCase()}`;const team=document.querySelector('#assistant-team');team.querySelector('span').textContent=status.franchise_name?'Selected team':'Team selection';team.querySelector('strong').textContent=status.franchise_name||'No team selected — choose one in My Account';team.classList.toggle('missing',!status.franchise_name);renderAssistantHistory();document.querySelector('#assistant-window').hidden=false;const launcher=document.querySelector('#assistant-launcher');launcher.hidden=true;launcher.setAttribute('aria-expanded','true');document.querySelector('#assistant-input').focus()}catch(error){toast(error.message,true)}}
function closeAssistant(){document.querySelector('#assistant-window').hidden=true;const launcher=document.querySelector('#assistant-launcher');launcher.hidden=false;launcher.setAttribute('aria-expanded','false')}
function newAssistantChat(){if(assistantSending)return toast('Wait for the current reply before starting a new chat',true);if(assistantHistory.length&&!confirm('Start a new chat? This clears the current conversation context.'))return;assistantHistory=[];if(assistantLeague)sessionStorage.removeItem(assistantStorageKey(assistantLeague));renderAssistantHistory();document.querySelector('#assistant-input').focus()}
function assistantComposerKeydown(event){if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();event.currentTarget.closest('form').requestSubmit()}}
async function askLeagueAssistant(event){event.preventDefault();if(assistantSending)return;const input=document.querySelector('#assistant-input'),message=input.value.trim();if(!message||!assistantLeague)return;const prior=assistantHistory.map(x=>({role:x.role,content:x.content})).slice(-20);assistantHistory.push({role:'user',content:message});saveAssistantHistory();renderAssistantHistory();input.value='';assistantSending=true;document.querySelector('#assistant-typing').hidden=false;event.currentTarget.querySelector('button[type=submit]').disabled=true;try{const result=await api('/api/assistant',{method:'POST',body:JSON.stringify({league_id:assistantLeague,message,history:prior})});assistantHistory.push({role:'assistant',content:result.answer});saveAssistantHistory();renderAssistantHistory()}catch(error){toast(error.message,true)}finally{assistantSending=false;document.querySelector('#assistant-typing').hidden=true;event.currentTarget.querySelector('button[type=submit]').disabled=false;input.focus()}}

// Bye-week roster coverage and matchup-aware available-player recommendations.
let byeAdvisorData=null;let byeAdvisorAutoSelect=false;
async function initByeAdvisor(){const params=new URL(location.href).searchParams,requested=params.get('week'),player=params.get('player_id');byeAdvisorAutoSelect=!requested&&!player;if(requested)document.querySelector('#bye-week').value=requested;if(player)document.querySelector('#bye-player').dataset.requested=player;await loadByeAdvisor()}
function chooseByeWeek(week){document.querySelector('#bye-week').value=String(week);const url=new URL(location.href);url.searchParams.set('week',week);history.replaceState({},'',url);loadByeAdvisor()}
async function loadByeAdvisor(){if(!BYE_LEAGUE_ID)return toast('Choose a league first',true);const week=Number(document.querySelector('#bye-week').value)||1,playerSelect=document.querySelector('#bye-player'),playerId=playerSelect.value||playerSelect.dataset.requested||'';try{byeAdvisorData=await api(`/api/leagues/${encodeURIComponent(BYE_LEAGUE_ID)}/bye-advisor?week=${week}${playerId?`&player_id=${encodeURIComponent(playerId)}`:''}`);playerSelect.dataset.requested='';if(byeAdvisorAutoSelect&&byeAdvisorData.configured&&!playerId){byeAdvisorAutoSelect=false;const firstBye=byeAdvisorData.week_summary.find(x=>x.bye_count>0);if(firstBye&&firstBye.week!==week){document.querySelector('#bye-week').value=String(firstBye.week);const url=new URL(location.href);url.searchParams.set('week',firstBye.week);history.replaceState({},'',url);return loadByeAdvisor()}}const url=new URL(location.href);url.searchParams.set('week',week);if(playerId)url.searchParams.set('player_id',playerId);else url.searchParams.delete('player_id');history.replaceState({},'',url);renderByeAdvisor()}catch(error){toast(error.message,true);document.querySelector('#bye-results').innerHTML=`<article class="notice warning">${escapeHtml(error.message)}</article>`}}
function renderByeAdvisor(){const data=byeAdvisorData,team=document.querySelector('#bye-team'),playerSelect=document.querySelector('#bye-player');if(!data.configured){team.className='notice warning';team.innerHTML='<strong>No team selected.</strong> Choose your MFL franchise in <a href="/account">My Account</a> before using the Bye Week Advisor.';playerSelect.innerHTML='<option value="">Select a team first</option>';document.querySelector('#bye-week-strip').innerHTML='';document.querySelector('#bye-results').innerHTML='<article class="panel"><h2>Select your team first</h2><p>The advisor needs your current roster to find bye-week gaps.</p></article>';return}const selected=data.selected_player_id||'';playerSelect.innerHTML='<option value="">All players on bye</option>'+data.roster.map(row=>`<option value="${escapeHtml(row.player_id)}">${escapeHtml(row.player_name)} · ${escapeHtml(row.position)} · bye ${row.bye_week??'—'}</option>`).join('');playerSelect.value=selected;team.className='notice success';team.innerHTML=`Advising <strong>${escapeHtml(data.franchise.name)}</strong> in ${escapeHtml(data.league.name)} · ${data.roster.length} active roster players`;document.querySelector('#bye-week-strip').innerHTML=data.week_summary.map(x=>`<button class="bye-week-button ${x.week===data.selected_week?'active':''} ${x.bye_count?'has-bye':''}" onclick="chooseByeWeek(${x.week})"><span>W${x.week}</span><strong>${x.bye_count}</strong></button>`).join('');const results=document.querySelector('#bye-results');if(!data.conflicts.length){results.innerHTML=`<article class="panel bye-clear"><span>✓</span><div><h2>No roster byes in Week ${data.selected_week}</h2><p>Your active roster has no players marked with a bye this week.</p></div></article>`}else{const manual=data.conflicts.some(row=>row.selected_manually);results.innerHTML=`<div class="bye-summary"><strong>${data.conflicts.length}</strong><span>${manual?'selected player comparison':`roster bye${data.conflicts.length===1?'':'s'}`} in Week ${data.selected_week}</span></div>`+data.conflicts.map(conflict=>`<article class="panel bye-conflict"><div class="bye-conflict-head"><div><span class="pill">${escapeHtml(conflict.position)} ${conflict.is_bye?'bye':'comparison'}</span><h2>${escapeHtml(conflict.player_name)}</h2><p>${escapeHtml(conflict.nfl_team||'FA')} · Overall rank ${conflict.overall_rank?`#${conflict.overall_rank}`:'unranked'}${conflict.is_bye?' · On bye this week':' · Not on bye this week'}</p></div><a class="button" href="/player/${encodeURIComponent(conflict.player_id)}?league_id=${encodeURIComponent(BYE_LEAGUE_ID)}">Profile</a></div><h3>Best available replacements</h3><div class="table-wrap"><table><thead><tr><th>Advisor</th><th>Player</th><th>Overall</th><th>Week ${data.selected_week}</th><th>Matchup</th></tr></thead><tbody>${conflict.recommendations.map((row,index)=>`<tr><td><strong>${index+1}</strong><small class="subrank">${row.recommendation_score}</small></td><td><a class="player-name-link" href="/player/${encodeURIComponent(row.player_id)}?league_id=${encodeURIComponent(BYE_LEAGUE_ID)}"><strong>${escapeHtml(row.player_name)}</strong></a><small class="subrank">${escapeHtml(row.nfl_team||'FA')} · ${escapeHtml(row.position)}</small></td><td>#${row.overall_rank}</td><td>${row.opponent?`${row.home_away==='home'?'vs':'@'} ${escapeHtml(row.opponent)}`:'Schedule unavailable'}</td><td><span class="matchup-badge ${String(row.matchup_label).toLowerCase()}">${escapeHtml(row.matchup_label)}</span>${row.matchup_rank?`<small class="subrank">${row.matchup_rank} of ${row.matchup_pool}</small>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No available same-position replacements were found.</td></tr>'}</tbody></table></div></article>`).join('')}document.querySelector('#bye-data-status').textContent=data.weekly_matchups_available?'Weekly opponents and matchup grades are available from nflverse.':data.schedule_available?'Opponents are loaded. Matchup grades use full-season schedule difficulty until nflverse is refreshed under Sources.':'Schedule data is not available yet. Recommendations currently rely on overall ranking; refresh nflverse under Sources.'}
